-- HemoCura Decision Chain 50 access hardening. Applied live as 20261012112931.
-- RLS for newly introduced tables.
alter table public.customer_payments enable row level security;drop policy if exists customer_payments_select on public.customer_payments;drop policy if exists customer_payments_insert on public.customer_payments;drop policy if exists customer_payments_update on public.customer_payments;drop policy if exists customer_payments_delete on public.customer_payments;create policy customer_payments_select on public.customer_payments for select to authenticated using(has_permission('COLLECTIONS_VIEW') and (branch_id is null or can_access_branch(branch_id)));create policy customer_payments_insert on public.customer_payments for insert to authenticated with check(has_permission('COLLECTIONS_WRITE') and (branch_id is null or can_access_branch(branch_id)));create policy customer_payments_update on public.customer_payments for update to authenticated using(has_permission('COLLECTIONS_WRITE') and (branch_id is null or can_access_branch(branch_id))) with check(has_permission('COLLECTIONS_WRITE') and (branch_id is null or can_access_branch(branch_id)));create policy customer_payments_delete on public.customer_payments for delete to authenticated using(has_permission('COLLECTIONS_WRITE') and (branch_id is null or can_access_branch(branch_id)));grant select,insert,update,delete on public.customer_payments to authenticated;
alter table public.inventory_loss_events enable row level security;drop policy if exists inventory_loss_select on public.inventory_loss_events;drop policy if exists inventory_loss_insert on public.inventory_loss_events;drop policy if exists inventory_loss_update on public.inventory_loss_events;drop policy if exists inventory_loss_delete on public.inventory_loss_events;create policy inventory_loss_select on public.inventory_loss_events for select to authenticated using(has_permission('ECONOMICS_VIEW') and can_access_branch(branch_id));create policy inventory_loss_insert on public.inventory_loss_events for insert to authenticated with check(has_permission('ECONOMICS_WRITE') and can_access_branch(branch_id));create policy inventory_loss_update on public.inventory_loss_events for update to authenticated using(has_permission('ECONOMICS_WRITE') and can_access_branch(branch_id)) with check(has_permission('ECONOMICS_WRITE') and can_access_branch(branch_id));create policy inventory_loss_delete on public.inventory_loss_events for delete to authenticated using(has_permission('ECONOMICS_WRITE') and can_access_branch(branch_id));grant select,insert,update,delete on public.inventory_loss_events to authenticated;
alter table public.medical_referrers enable row level security;drop policy if exists medical_referrers_select on public.medical_referrers;drop policy if exists medical_referrers_insert on public.medical_referrers;drop policy if exists medical_referrers_update on public.medical_referrers;drop policy if exists medical_referrers_delete on public.medical_referrers;create policy medical_referrers_select on public.medical_referrers for select to authenticated using(has_permission('MEDICAL_NETWORK_VIEW') and (branch_id is null or can_access_branch(branch_id)));create policy medical_referrers_insert on public.medical_referrers for insert to authenticated with check(has_permission('MEDICAL_NETWORK_WRITE') and (branch_id is null or can_access_branch(branch_id)));create policy medical_referrers_update on public.medical_referrers for update to authenticated using(has_permission('MEDICAL_NETWORK_WRITE') and (branch_id is null or can_access_branch(branch_id))) with check(has_permission('MEDICAL_NETWORK_WRITE') and (branch_id is null or can_access_branch(branch_id)));create policy medical_referrers_delete on public.medical_referrers for delete to authenticated using(has_permission('MEDICAL_NETWORK_WRITE') and (branch_id is null or can_access_branch(branch_id)));grant select,insert,update,delete on public.medical_referrers to authenticated;
alter table public.medical_referral_events enable row level security;drop policy if exists medical_referral_events_select on public.medical_referral_events;drop policy if exists medical_referral_events_insert on public.medical_referral_events;drop policy if exists medical_referral_events_update on public.medical_referral_events;drop policy if exists medical_referral_events_delete on public.medical_referral_events;create policy medical_referral_events_select on public.medical_referral_events for select to authenticated using(has_permission('MEDICAL_NETWORK_VIEW') and (branch_id is null or can_access_branch(branch_id)));create policy medical_referral_events_insert on public.medical_referral_events for insert to authenticated with check(has_permission('MEDICAL_NETWORK_WRITE') and (branch_id is null or can_access_branch(branch_id)));create policy medical_referral_events_update on public.medical_referral_events for update to authenticated using(has_permission('MEDICAL_NETWORK_WRITE') and (branch_id is null or can_access_branch(branch_id))) with check(has_permission('MEDICAL_NETWORK_WRITE') and (branch_id is null or can_access_branch(branch_id)));create policy medical_referral_events_delete on public.medical_referral_events for delete to authenticated using(has_permission('MEDICAL_NETWORK_WRITE') and (branch_id is null or can_access_branch(branch_id)));grant select,insert,update,delete on public.medical_referral_events to authenticated;
-- Reconcile legacy core policies with the new decision permissions.
drop policy if exists demand_branch_read on public.clinical_demand_requests;drop policy if exists demand_branch_insert on public.clinical_demand_requests;drop policy if exists demand_branch_update on public.clinical_demand_requests;drop policy if exists demand_branch_delete on public.clinical_demand_requests;create policy demand_branch_read on public.clinical_demand_requests for select to authenticated using(can_access_branch(branch_id) and (has_permission('VALUE_CHAIN_VIEW') or has_permission('SUPPLY_VIEW') or has_permission('DISPATCH_VIEW') or has_permission('SERVICE_PERFORMANCE_VIEW') or has_permission('MEDICAL_NETWORK_VIEW')));create policy demand_branch_insert on public.clinical_demand_requests for insert to authenticated with check(can_access_branch(branch_id) and (has_permission('VALUE_CHAIN_WRITE') or has_permission('SUPPLY_WRITE') or has_permission('DISPATCH_WRITE') or has_permission('SERVICE_PERFORMANCE_WRITE')));create policy demand_branch_update on public.clinical_demand_requests for update to authenticated using(can_access_branch(branch_id) and (has_permission('VALUE_CHAIN_WRITE') or has_permission('SUPPLY_WRITE') or has_permission('DISPATCH_WRITE') or has_permission('SERVICE_PERFORMANCE_WRITE'))) with check(can_access_branch(branch_id) and (has_permission('VALUE_CHAIN_WRITE') or has_permission('SUPPLY_WRITE') or has_permission('DISPATCH_WRITE') or has_permission('SERVICE_PERFORMANCE_WRITE')));create policy demand_branch_delete on public.clinical_demand_requests for delete to authenticated using(can_access_branch(branch_id) and (has_permission('VALUE_CHAIN_WRITE') or has_permission('SUPPLY_WRITE') or has_permission('DISPATCH_WRITE')));
drop policy if exists dispatches_branch_select on public.dispatches;drop policy if exists dispatches_branch_insert on public.dispatches;drop policy if exists dispatches_branch_update on public.dispatches;drop policy if exists dispatches_branch_delete on public.dispatches;create policy dispatches_branch_select on public.dispatches for select to authenticated using(can_access_branch(branch_id) and (has_permission('DISPATCH_VIEW') or has_permission('SERVICE_PERFORMANCE_VIEW') or has_permission('VALUE_CHAIN_VIEW')));create policy dispatches_branch_insert on public.dispatches for insert to authenticated with check(can_access_branch(branch_id) and has_permission('DISPATCH_WRITE'));create policy dispatches_branch_update on public.dispatches for update to authenticated using(can_access_branch(branch_id) and (has_permission('DISPATCH_WRITE') or has_permission('SERVICE_PERFORMANCE_WRITE'))) with check(can_access_branch(branch_id) and (has_permission('DISPATCH_WRITE') or has_permission('SERVICE_PERFORMANCE_WRITE')));create policy dispatches_branch_delete on public.dispatches for delete to authenticated using(can_access_branch(branch_id) and has_permission('DISPATCH_WRITE'));
drop policy if exists operational_sales_branch_access on public.operational_sales;drop policy if exists operational_sales_select on public.operational_sales;drop policy if exists operational_sales_insert on public.operational_sales;drop policy if exists operational_sales_update on public.operational_sales;drop policy if exists operational_sales_delete on public.operational_sales;create policy operational_sales_select on public.operational_sales for select to authenticated using(can_access_branch(branch_id) and (has_permission('SALES_VIEW') or has_permission('COLLECTIONS_VIEW') or has_permission('ECONOMICS_VIEW') or has_permission('CUSTOMER_VIEW') or has_permission('VALUE_CHAIN_VIEW')));create policy operational_sales_insert on public.operational_sales for insert to authenticated with check(can_access_branch(branch_id) and has_permission('SALES_WRITE'));create policy operational_sales_update on public.operational_sales for update to authenticated using(can_access_branch(branch_id) and has_permission('SALES_WRITE')) with check(can_access_branch(branch_id) and has_permission('SALES_WRITE'));create policy operational_sales_delete on public.operational_sales for delete to authenticated using(can_access_branch(branch_id) and has_permission('SALES_WRITE'));
drop policy if exists operational_sale_lines_access on public.operational_sale_lines;drop policy if exists operational_sale_lines_select on public.operational_sale_lines;drop policy if exists operational_sale_lines_insert on public.operational_sale_lines;drop policy if exists operational_sale_lines_update on public.operational_sale_lines;drop policy if exists operational_sale_lines_delete on public.operational_sale_lines;create policy operational_sale_lines_select on public.operational_sale_lines for select to authenticated using(exists(select 1 from public.operational_sales s where s.id=operational_sale_lines.sale_id and can_access_branch(s.branch_id) and (has_permission('SALES_VIEW') or has_permission('ECONOMICS_VIEW') or has_permission('CUSTOMER_VIEW'))));create policy operational_sale_lines_insert on public.operational_sale_lines for insert to authenticated with check(exists(select 1 from public.operational_sales s where s.id=operational_sale_lines.sale_id and can_access_branch(s.branch_id) and has_permission('SALES_WRITE')));create policy operational_sale_lines_update on public.operational_sale_lines for update to authenticated using(exists(select 1 from public.operational_sales s where s.id=operational_sale_lines.sale_id and can_access_branch(s.branch_id) and has_permission('SALES_WRITE'))) with check(exists(select 1 from public.operational_sales s where s.id=operational_sale_lines.sale_id and can_access_branch(s.branch_id) and has_permission('SALES_WRITE')));create policy operational_sale_lines_delete on public.operational_sale_lines for delete to authenticated using(exists(select 1 from public.operational_sales s where s.id=operational_sale_lines.sale_id and can_access_branch(s.branch_id) and has_permission('SALES_WRITE')));
drop policy if exists customers_read on public.customers;create policy customers_read on public.customers for select to authenticated using(has_permission('CUSTOMER_VIEW') or has_permission('SALES_VIEW') or has_permission('DISPATCH_VIEW') or has_permission('COLLECTIONS_VIEW') or has_permission('ECONOMICS_VIEW') or has_permission('MEDICAL_NETWORK_VIEW') or has_permission('VALUE_CHAIN_VIEW'));
drop policy if exists donor_campaigns_read on public.donor_campaigns;drop policy if exists donor_campaigns_update on public.donor_campaigns;create policy donor_campaigns_read on public.donor_campaigns for select to authenticated using((has_permission('DONOR_OUTREACH_VIEW') or has_permission('ECONOMICS_VIEW')) and (branch_id is null or can_access_branch(branch_id)));create policy donor_campaigns_update on public.donor_campaigns for update to authenticated using((has_permission('DONOR_OUTREACH_WRITE') or has_permission('ECONOMICS_WRITE')) and (branch_id is null or can_access_branch(branch_id))) with check((has_permission('DONOR_OUTREACH_WRITE') or has_permission('ECONOMICS_WRITE')) and (branch_id is null or can_access_branch(branch_id)));
drop policy if exists mcp_read on public.monthly_cost_periods;drop policy if exists mcp_write on public.monthly_cost_periods;create policy mcp_read on public.monthly_cost_periods for select to authenticated using(can_access_branch(branch_id) and (has_permission('ECONOMICS_VIEW') or has_role('ADMIN') or has_role('FINANZAS') or has_role('GERENCIA_OPERATIVA') or has_role('GERENCIA_GENERAL')));create policy mcp_write on public.monthly_cost_periods for all to authenticated using(can_access_branch(branch_id) and (has_role('ADMIN') or has_role('FINANZAS') or has_role('GERENCIA_OPERATIVA'))) with check(can_access_branch(branch_id) and (has_role('ADMIN') or has_role('FINANZAS') or has_role('GERENCIA_OPERATIVA')));drop policy if exists mpc_read on public.monthly_product_costs;create policy mpc_read on public.monthly_product_costs for select to authenticated using(can_access_branch(branch_id) and (has_permission('ECONOMICS_VIEW') or has_role('ADMIN') or has_role('FINANZAS') or has_role('GERENCIA_OPERATIVA') or has_role('GERENCIA_GENERAL')));drop policy if exists products_read on public.products;create policy products_read on public.products for select to authenticated using(true);
create or replace view public.vw_customer_profitability with (security_invoker=true) as select s.customer_id,coalesce(c.name,s.customer_name) customer_name,s.branch_id,count(distinct s.id) sales_count,sum(s.total_amount) revenue,sum(coalesce(cp.paid,0)) collected,sum(coalesce(costs.estimated_cost,0)) estimated_cost,sum(s.total_amount-coalesce(costs.estimated_cost,0)) contribution_margin,case when sum(s.total_amount)>0 then round(100.0*sum(s.total_amount-coalesce(costs.estimated_cost,0))/sum(s.total_amount),1) end margin_pct from public.operational_sales s left join public.customers c on c.id=s.customer_id left join lateral(select sum(p.amount) paid from public.customer_payments p where p.sale_id=s.id)cp on true left join lateral(select sum(sl.quantity*coalesce(mc.cost_per_unit,0)) estimated_cost from public.operational_sale_lines sl left join lateral(select mpc.cost_per_unit from public.monthly_product_costs mpc join public.monthly_cost_periods mp on mp.id=mpc.period_id where mpc.product_id=sl.product_id and mpc.branch_id=s.branch_id and mp.period_month<=date_trunc('month',s.sale_date)::date order by mp.period_month desc limit 1)mc on true where sl.sale_id=s.id)costs on true where s.status is distinct from 'CANCELADA' group by s.customer_id,coalesce(c.name,s.customer_name),s.branch_id;
create or replace view public.vw_branch_contribution with (security_invoker=true) as select b.id branch_id,b.code branch_code,b.name branch_name,coalesce(p.revenue,0) revenue,coalesce(p.collected,0) collected,coalesce(p.estimated_cost,0) estimated_cost,coalesce(l.loss_amount,0) inventory_loss,coalesce(p.revenue,0)-coalesce(p.estimated_cost,0)-coalesce(l.loss_amount,0) contribution_after_loss,coalesce(ar.outstanding,0) accounts_receivable from public.branches b left join(select branch_id,sum(revenue) revenue,sum(collected) collected,sum(estimated_cost) estimated_cost from public.vw_customer_profitability group by branch_id)p on p.branch_id=b.id left join(select branch_id,sum(estimated_loss) loss_amount from public.inventory_loss_events group by branch_id)l on l.branch_id=b.id left join(select branch_id,sum(outstanding_amount) outstanding from public.vw_accounts_receivable group by branch_id)ar on ar.branch_id=b.id where b.active=true;
create or replace view public.vw_decision_action_candidates with (security_invoker=true) as select ('DEMAND:'||d.demand_request_id::text) candidate_key,d.branch_id,'DEMANDA' source_domain,'clinical_demand_requests' source_table,d.demand_request_id source_id,'Demanda fuera de SLA' title,('Cliente: '||coalesce(d.customer_name,'Sin cliente')||' · prioridad '||coalesce(d.priority,'N/D')) description,case when d.priority in('CRITICA','URGENTE') then 'CRITICA' else 'ALTA' end priority,current_date due_date from public.vw_service_level_performance d where d.sla_status='FUERA_SLA' and not exists(select 1 from public.integrated_actions a where a.source_table='clinical_demand_requests' and a.source_id=d.demand_request_id and a.status not in('CANCELADA','CERRADA')) union all select ('AR:'||a.sale_id::text),a.branch_id,'COBRANZA','operational_sales',a.sale_id,'Cuenta por cobrar vencida',('Cliente: '||coalesce(a.customer_name,'Sin cliente')||' · RD$ '||round(a.outstanding_amount,2)::text||' · aging '||a.aging_bucket),case when a.days_past_due>90 then 'CRITICA' when a.days_past_due>60 then 'ALTA' else 'MEDIA' end,current_date+7 from public.vw_accounts_receivable a where a.outstanding_amount>0 and a.days_past_due>30 and not exists(select 1 from public.integrated_actions ia where ia.source_table='operational_sales' and ia.source_id=a.sale_id and ia.status not in('CANCELADA','CERRADA')) union all select ('LOSS:'||l.id::text),l.branch_id,'MERMA','inventory_loss_events',l.id,'Pérdida de inventario',('Tipo: '||l.loss_type||' · RD$ '||round(l.estimated_loss,2)::text||' · '||l.reason),case when l.estimated_loss>=10000 then 'ALTA' else 'MEDIA' end,current_date+7 from public.inventory_loss_events l where l.linked_action_id is null union all select ('FB:'||f.id::text),f.branch_id,'CLIENTE','customer_feedback',f.id,'Seguimiento de cliente requerido',coalesce(f.description,'Feedback pendiente'),case when f.feedback_type='QUEJA' then 'ALTA' else 'MEDIA' end,current_date+5 from public.customer_feedback f where f.requires_followup=true and f.status<>'CERRADO' and f.linked_action_id is null;
grant select on public.vw_customer_profitability,public.vw_branch_contribution,public.vw_decision_action_candidates to authenticated;
